#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Run VGGT-SLAM 2.0 from source and save final eval outputs + RRD internally.

This script runs VGGT-SLAM 2.0 directly (bypassing the wrapper), performs
pose-Sim3 alignment, and saves:

  <output_rrd>
  <output_dir>/eval/pred_points.ply
  <output_dir>/eval/gt_points.ply
  <output_dir>/eval/pred_cameras.npz
  <output_dir>/eval/gt_cameras.npz
  <output_dir>/eval/meta.json

The benchmark shell should only call this source script and then compute metrics.
"""
from __future__ import annotations

import argparse
import fnmatch
import json
import os
import shutil
import sys
import time
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple


# ---- Pre-import path setup (must happen before any vggt_slam import) ----
def _preconfigure_cuda_from_argv() -> None:
    argv = sys.argv
    dev = None
    for i, a in enumerate(argv):
        if a == "--device" and i + 1 < len(argv):
            dev = argv[i + 1]
            break
    if dev is None:
        return
    s = str(dev).lower()
    if s == "cpu":
        os.environ["CUDA_VISIBLE_DEVICES"] = ""
    elif s.isdigit():
        os.environ["CUDA_VISIBLE_DEVICES"] = s
    elif s.startswith("cuda:") and s.split(":", 1)[1].isdigit():
        os.environ["CUDA_VISIBLE_DEVICES"] = s.split(":", 1)[1]


_preconfigure_cuda_from_argv()

import cv2
import numpy as np
import torch
from tqdm.auto import tqdm

# Make repo root importable for spatial_rrd.
_THIS = Path(__file__).resolve()
_REPO_ROOT = _THIS.parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

# Local VGGT-SPARK path.
_VGGT_REPO = os.environ.get("VGGT_REPO")
if not _VGGT_REPO:
    _VGGT_REPO = _THIS.parent / "third_party" / "vggt"
if _VGGT_REPO and Path(_VGGT_REPO).exists() and (Path(_VGGT_REPO) / "vggt").is_dir():
    sys.path.insert(0, str(Path(_VGGT_REPO).resolve()))

_SALAD_REPO = _THIS.parent / "third_party" / "salad"
if (_SALAD_REPO / "salad").is_dir():
    sys.path.insert(0, str(_SALAD_REPO.resolve()))

import vggt_slam.slam_utils as utils
from vggt_slam.solver import Solver
from vggt_slam.local_weights import configure_vggt_slam_runtime, load_vggt_weights
from vggt_slam.vggt_source import build_vggt_from_local_path
from vggt_slam.export_rrd import (
    IMAGE_EXTS,
    collect_stem_to_path,
    export_solver_outputs,
    json_safe,
    sanitize_name,
)


def contiguous_select(items: Sequence[str], max_count: int) -> List[str]:
    items = list(items)
    if int(max_count) <= 0 or len(items) <= int(max_count):
        return items
    return items[: int(max_count)]


def select_images(args: argparse.Namespace) -> Tuple[List[str], List[Path]]:
    scene_dir = Path(args.scene_dir).expanduser().resolve()
    images_dir = scene_dir / args.images_dir
    images = collect_stem_to_path(images_dir, IMAGE_EXTS)
    if not images:
        raise RuntimeError(f"No images found under {images_dir}")

    stems = sorted(images)
    if args.frame_glob and args.frame_glob != "*":
        stems = [s for s in stems if fnmatch.fnmatch(s, args.frame_glob)]
    if int(args.start) > 0:
        stems = stems[int(args.start) :]
    if int(args.stride) > 1:
        stems = stems[:: int(args.stride)]
    stems = contiguous_select(stems, int(args.num_views))
    if not stems:
        raise RuntimeError(f"No frames selected under {images_dir}")

    return stems, [images[s] for s in stems]


def round_down_to_multiple(x: int, multiple: int) -> int:
    if int(multiple) <= 1:
        return int(x)
    return max(int(multiple), int(x) // int(multiple) * int(multiple))


def target_hw(height: int, width: int, max_side: int, size_multiple: int) -> Tuple[int, int]:
    h, w = int(height), int(width)
    if int(max_side) > 0 and max(h, w) > int(max_side):
        scale = float(max_side) / float(max(h, w))
        h = max(1, int(round(h * scale)))
        w = max(1, int(round(w * scale)))
    return round_down_to_multiple(h, size_multiple), round_down_to_multiple(w, size_multiple)


def materialize_images(
    image_paths: Sequence[Path],
    stems: Sequence[str],
    out_dir: Path,
    max_side: int,
    size_multiple: int,
    copy_images: bool,
):
    marker = out_dir / ".mapanything_vggt_slam2_input"
    if out_dir.exists():
        if not marker.exists():
            raise RuntimeError(
                f"Refusing to overwrite existing input folder without marker: {out_dir}"
            )
        shutil.rmtree(out_dir)

    out_dir.mkdir(parents=True, exist_ok=True)
    marker.write_text(
        "generated by third_party/vggt-slam2.0/run_scene_to_rrd.py\n", encoding="utf-8"
    )

    materialized = []
    metadata = []
    for i, (src, stem) in enumerate(zip(image_paths, stems)):
        dst = out_dir / f"{i:06d}__{sanitize_name(stem)}{src.suffix.lower()}"
        img = cv2.imread(str(src), cv2.IMREAD_COLOR)
        if img is None:
            raise RuntimeError(f"Cannot read image: {src}")

        src_h, src_w = img.shape[:2]
        dst_h, dst_w = target_hw(
            src_h, src_w, max_side=max_side, size_multiple=size_multiple
        )
        resized = (dst_h, dst_w) != (src_h, src_w)

        if resized or copy_images:
            if resized:
                img = cv2.resize(img, (dst_w, dst_h), interpolation=cv2.INTER_AREA)
            if not cv2.imwrite(str(dst), img):
                raise RuntimeError(f"Failed to write prepared image: {dst}")
        else:
            try:
                os.symlink(src, dst)
            except OSError:
                shutil.copy2(src, dst)

        materialized.append(dst)
        metadata.append(
            {
                "index": int(i),
                "stem": str(stem),
                "source": str(src),
                "prepared": str(dst),
                "source_size": {"height": int(src_h), "width": int(src_w)},
                "prepared_size": {"height": int(dst_h), "width": int(dst_w)},
                "resized": bool(resized),
            }
        )
    return materialized, metadata


def run_vggt_slam2(
    args: argparse.Namespace, prepared_dir: Path
) -> Tuple[Solver, List[str], Dict[str, object]]:
    device = (
        "cuda"
        if torch.cuda.is_available() and str(args.device).lower() != "cpu"
        else "cpu"
    )
    print(f"Using device: {device}")

    configure_vggt_slam_runtime(
        torch_hub_dir=args.torch_hub_dir, offline=args.offline
    )

    solver = Solver(
        init_conf_threshold=float(args.conf_threshold),
        lc_thres=float(args.lc_thres),
        vis_voxel_size=args.vis_voxel_size,
        headless=True,
    )

    print("Initializing and loading VGGT-SPARK model...")
    model = build_vggt_from_local_path(
        vggt_repo=args.vggt_repo,
        default_relative_path="third_party/vggt",
    )
    load_vggt_weights(model, model_path=args.vggt_model_path, offline=args.offline)
    model.eval()
    model = model.to(torch.bfloat16)
    model = model.to(device)
    if device == "cuda":
        torch.cuda.synchronize(device)
        torch.cuda.reset_peak_memory_stats(device)

    image_names = [
        str(p)
        for p in sorted(prepared_dir.iterdir())
        if p.is_file()
        and p.suffix.lower() in IMAGE_EXTS
        and "depth" not in p.name.lower()
        and "txt" not in p.name.lower()
        and "db" not in p.name.lower()
    ]
    image_names = utils.sort_images_by_number(image_names)
    print(f"Found {len(image_names)} prepared images")

    use_optical_flow_downsample = not bool(args.disable_keyframe_selection)

    processing_time_start = time.perf_counter()
    total_time_start = time.time()

    image_names_subset = []
    image_count = 0
    keyframe_time = utils.Accumulator()
    backend_time = utils.Accumulator()

    for image_name in tqdm(image_names, dynamic_ncols=True):
        if use_optical_flow_downsample:
            with keyframe_time:
                img = cv2.imread(image_name)
                enough_disparity = solver.flow_tracker.compute_disparity(
                    img,
                    float(args.min_disparity),
                    bool(args.vis_flow),
                )
                if enough_disparity:
                    image_names_subset.append(image_name)
                    image_count += 1
        else:
            image_names_subset.append(image_name)
            image_count += 1

        ready = len(image_names_subset) == int(args.submap_size) + int(
            args.overlapping_window_size
        )
        last = image_name == image_names[-1]
        if ready or last:
            if len(image_names_subset) == 0:
                continue

            t1 = time.time()
            predictions = solver.run_predictions(
                image_names_subset,
                model,
                int(args.max_loops),
                None,
                None,
            )
            print(f"Solver prediction time: {time.time() - t1:.3f}s")

            solver.add_points(predictions)

            with backend_time:
                solver.graph.optimize()

            image_names_subset = image_names_subset[
                -int(args.overlapping_window_size) :
            ]

    processing_time_seconds = time.perf_counter() - processing_time_start
    if device == "cuda":
        torch.cuda.synchronize(device)
        peak_allocated = int(torch.cuda.max_memory_allocated(device))
        peak_reserved = int(torch.cuda.max_memory_reserved(device))
    else:
        peak_allocated = 0
        peak_reserved = 0
    total_time = time.time() - total_time_start

    timing_payload = {
        "schema": "processing_time_v1",
        "method": "vggt-slam2.0",
        "processing_time_seconds": float(processing_time_seconds),
        "processing_time_ms": float(processing_time_seconds * 1000.0),
        "start_event": "after_vggt_weights_loaded",
        "end_event": "before_source_internal_export",
        "excluded": ["weight_loading", "final_result_saving"],
        "num_input_images": int(len(image_names)),
        "num_processed_frames": int(image_count),
        "num_submaps": int(solver.map.get_num_submaps()),
        "num_loop_closures": int(solver.graph.get_num_loops()),
        "peak_gpu_memory_allocated_bytes": peak_allocated,
        "peak_gpu_memory_allocated_mib": float(peak_allocated / (1024 ** 2)),
        "peak_gpu_memory_reserved_bytes": peak_reserved,
        "peak_gpu_memory_reserved_mib": float(peak_reserved / (1024 ** 2)),
        "components": {
            "vggt_seconds": float(solver.vggt_timer.total_time),
            "loop_closure_seconds": float(solver.loop_closure_timer.total_time),
            "keyframe_selection_seconds": float(keyframe_time.total_time),
            "backend_seconds": float(backend_time.total_time),
            "total_runtime_seconds": float(total_time),
        },
    }

    print(
        f"Processing time (excluding weights/final saving): {processing_time_seconds:.6f}s"
    )
    print("Total number of submaps in map", solver.map.get_num_submaps())
    print("Total number of loop closures in map", solver.graph.get_num_loops())
    return solver, image_names, timing_payload


def parse_args(argv: Optional[Sequence[str]] = None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--method", default="vggt-slam2.0")
    parser.add_argument("--scene_dir", required=True)
    parser.add_argument("--output_rrd", required=True)
    parser.add_argument("--output_dir", default=None)
    parser.add_argument("--device", default="auto")
    parser.add_argument("--seed", type=int, default=0)

    parser.add_argument("--images_dir", default="images")
    parser.add_argument("--cams_dir", default="cams")
    parser.add_argument("--depth_dir", default="depth")
    parser.add_argument("--frame_glob", default="*")
    parser.add_argument("--num_views", type=int, default=0)
    parser.add_argument("--start", type=int, default=0)
    parser.add_argument("--stride", type=int, default=1)
    parser.add_argument("--max_side", type=int, default=518)
    parser.add_argument("--size_multiple", type=int, default=14)
    parser.add_argument("--copy_images", action="store_true")

    parser.add_argument("--depth_scale", type=float, default=1.0)
    parser.add_argument("--depth_min", type=float, default=1e-6)
    parser.add_argument("--depth_max", type=float, default=1e6)

    parser.add_argument("--submap_size", type=int, default=16)
    parser.add_argument("--overlapping_window_size", type=int, default=2)
    parser.add_argument("--max_loops", type=int, default=1)
    parser.add_argument("--min_disparity", type=float, default=50.0)
    parser.add_argument("--conf_threshold", type=float, default=25.0)
    parser.add_argument("--lc_thres", type=float, default=0.95)
    parser.add_argument("--vis_voxel_size", type=float, default=None)
    parser.add_argument("--vis_flow", action="store_true")
    parser.add_argument("--disable_keyframe_selection", action="store_true")

    parser.add_argument("--max_pred_points", type=int, default=500000)
    parser.add_argument("--max_gt_points", type=int, default=800000)
    parser.add_argument("--max_points_per_view", type=int, default=500000)
    parser.add_argument("--voxel_downsample", type=float, default=0.01)
    parser.add_argument("--global_point_stride", type=int, default=1)
    parser.add_argument(
        "--no_point_downsample", action="store_false", dest="point_downsample"
    )
    parser.set_defaults(point_downsample=True)

    parser.add_argument("--keep_intermediate", action="store_true")
    parser.add_argument("--vggt_model_path", default=None)
    parser.add_argument("--vggt_repo", default=None)
    parser.add_argument("--torch_hub_dir", default=None)
    parser.add_argument("--offline", action="store_true")

    # compatibility with common runner; ignored for 2.0
    parser.add_argument("--vggt_long_config", default=None)
    parser.add_argument("--headless", action="store_true", default=True)
    parser.add_argument("--no_headless", action="store_false", dest="headless")
    return parser.parse_args(argv)


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = parse_args(argv)

    output_rrd = Path(args.output_rrd).expanduser().resolve()
    output_dir = (
        Path(args.output_dir).expanduser().resolve()
        if args.output_dir
        else output_rrd.with_suffix("")
    )
    output_dir.mkdir(parents=True, exist_ok=True)
    prepared_dir = output_dir / "selected_images"

    stems, image_paths = select_images(args)
    prepared_images, prepared_metadata = materialize_images(
        image_paths=image_paths,
        stems=stems,
        out_dir=prepared_dir,
        max_side=int(args.max_side),
        size_multiple=int(args.size_multiple),
        copy_images=bool(args.copy_images),
    )
    print(
        f"Selected {len(prepared_images)} images for VGGT-SLAM 2.0 source export; "
        f"prepared input: {prepared_dir}"
    )

    if prepared_metadata:
        gt_target_h = int(prepared_metadata[0]["prepared_size"]["height"])
        gt_target_w = int(prepared_metadata[0]["prepared_size"]["width"])
    else:
        gt_target_h = None
        gt_target_w = None

    print(
        f"[VGGT-SLAM2][GT] spatial-compatible target size: "
        f"{gt_target_h}x{gt_target_w}, "
        f"max_side={int(args.max_side)}, size_multiple={int(args.size_multiple)}"
    )

    solver, image_names, timing_payload = run_vggt_slam2(args, prepared_dir)

    timing_path = output_dir / "processing_time.json"
    timing_path.write_text(
        json.dumps(json_safe(timing_payload), indent=2), encoding="utf-8"
    )

    # Debug only, not used for metric export.
    pose_log_path = output_dir / "poses.txt"
    solver.map.write_poses_to_file(
        str(pose_log_path), solver.graph, kitti_format=False
    )

    max_pred_points = int(
        args.max_points_per_view if args.point_downsample else args.max_pred_points
    )
    voxel_size = float(
        args.voxel_downsample if args.point_downsample else 0.0
    )

    meta = export_solver_outputs(
        solver=solver,
        image_names=image_names,
        output_rrd=output_rrd,
        eval_dir=output_dir / "eval",
        scene_dir=Path(args.scene_dir).expanduser().resolve(),
        images_dir=args.images_dir,
        cams_dir=args.cams_dir,
        depth_dir=args.depth_dir,
        depth_scale=float(args.depth_scale),
        depth_min=float(args.depth_min),
        depth_max=float(args.depth_max),
        max_pred_points=max_pred_points,
        max_gt_points=int(args.max_gt_points),
        voxel_size=voxel_size,
        point_stride=int(args.global_point_stride),
        seed=int(args.seed),
        processing_time=timing_payload,
        method="vggt-slam2.0",
        method_variant="default",
        gt_target_h=gt_target_h,
        gt_target_w=gt_target_w,
        max_side=int(args.max_side),
        size_multiple=int(args.size_multiple),
    )

    sidecar = output_rrd.with_suffix(".json")
    payload = {
        "method": "vggt-slam2.0",
        "requested_method": args.method,
        "scene_dir": str(Path(args.scene_dir).expanduser().resolve()),
        "output_rrd": str(output_rrd),
        "output_dir": str(output_dir),
        "prepared_dir": str(prepared_dir),
        "pose_log_path": str(pose_log_path),
        "timing_path": str(timing_path),
        "processing_time": timing_payload,
        "export": meta,
        "stems": stems,
        "prepared_images": prepared_metadata,
    }
    sidecar.write_text(
        json.dumps(json_safe(payload), indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print(f"Saved sidecar metadata: {sidecar}")

    if not bool(args.keep_intermediate):
        try:
            shutil.rmtree(prepared_dir)
            print(f"[CLEANUP] removed directory: {prepared_dir}")
        except Exception as exc:
            print(f"[CLEANUP][WARN] failed to remove {prepared_dir}: {exc}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
